CREATE OR REPLACE FUNCTION private.validate_attendance_shift_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_start public.attendance_verifications%rowtype;
  v_report public.daily_reports%rowtype;
  v_date date;
  v_legacy_start timestamptz;
  v_legacy_count integer;
begin
  -- Evidence chronology/ownership cannot be rewritten. Management corrects by
  -- replacing complete shifts, and photograph/report linking stays available.
  if TG_OP='UPDATE' then
    if row(NEW.id,NEW.company_id,NEW.worker_id,NEW.site_id,NEW.route_assignment_id,
           NEW.event_type,NEW.confirmed_at,NEW.source_clock_in_id,NEW.work_date)
       is distinct from
       row(OLD.id,OLD.company_id,OLD.worker_id,OLD.site_id,OLD.route_assignment_id,
           OLD.event_type,OLD.confirmed_at,OLD.source_clock_in_id,OLD.work_date) then
      raise exception 'attendance evidence chronology is immutable';
    end if;
    -- Preserve existing vehicle FK ON DELETE SET NULL while preventing edits.
    if NEW.vehicle_id is distinct from OLD.vehicle_id and not (
      NEW.vehicle_id is null and OLD.vehicle_id is not null and not exists (
        select 1 from public.vehicles v where v.id=OLD.vehicle_id
      )
    ) then raise exception 'attendance evidence vehicle is immutable'; end if;
    v_date := coalesce(NEW.work_date,(NEW.confirmed_at at time zone 'Asia/Tokyo')::date);
  else
    v_date := (NEW.confirmed_at at time zone 'Asia/Tokyo')::date;
  end if;

  if NEW.vehicle_id is not null and not exists (
    select 1 from public.vehicles v where v.id=NEW.vehicle_id and v.company_id=NEW.company_id
  ) then raise exception 'attendance vehicle does not belong to company'; end if;

  if NEW.source_clock_in_id is not null then
    if NEW.event_type <> 'clock_out' or NEW.source_clock_in_id=NEW.id then
      raise exception 'only clock out can reference its clock in';
    end if;
    -- SECURITY INVOKER: source visibility is governed by the existing RLS.
    select * into v_start from public.attendance_verifications
      where id=NEW.source_clock_in_id;
    if not found or v_start.event_type <> 'clock_in'
       or row(v_start.company_id,v_start.worker_id,v_start.site_id,v_start.route_assignment_id,v_start.vehicle_id)
          is distinct from row(NEW.company_id,NEW.worker_id,NEW.site_id,NEW.route_assignment_id,NEW.vehicle_id)
       or NEW.confirmed_at < v_start.confirmed_at then
      raise exception 'clock out source is unavailable or inconsistent';
    end if;
    if TG_OP='INSERT' and date_trunc('minute',NEW.confirmed_at at time zone 'Asia/Tokyo')
       = date_trunc('minute',v_start.confirmed_at at time zone 'Asia/Tokyo') then
      raise exception using errcode='22023',
        message='出勤と同じ時刻のため退勤できません。時刻が進んでから再度お試しください';
    end if;
    v_date := coalesce(v_start.work_date,(v_start.confirmed_at at time zone 'Asia/Tokyo')::date);
    if v_start.work_date is null and v_start.daily_report_id is not null then
      select * into v_report from public.daily_reports where id=v_start.daily_report_id;
      if not found or row(v_report.company_id,v_report.site_id,v_report.route_assignment_id)
         is distinct from row(NEW.company_id,NEW.site_id,NEW.route_assignment_id) then
        raise exception 'clock in report is inconsistent';
      end if;
      v_date := v_report.report_date;
    end if;
    if TG_OP='INSERT' and exists (
      select 1 from public.attendance_verifications a
      where a.company_id=NEW.company_id and a.worker_id=NEW.worker_id
        and a.site_id is not distinct from NEW.site_id
        and a.route_assignment_id is not distinct from NEW.route_assignment_id
        and a.confirmed_at >= v_start.confirmed_at
        and a.confirmed_at <= NEW.confirmed_at
        and a.event_type='clock_out' and a.source_clock_in_id is null
    ) then
      raise exception 'clock in is already closed or its evidence is ambiguous';
    end if;
  end if;

  if NEW.daily_report_id is not null then
    select * into v_report from public.daily_reports where id=NEW.daily_report_id;
    if not found or row(v_report.company_id,v_report.site_id,v_report.route_assignment_id)
       is distinct from row(NEW.company_id,NEW.site_id,NEW.route_assignment_id)
       or (NEW.source_clock_in_id is not null and v_report.report_date <> v_date)
       or (NEW.work_date is not null and TG_OP='UPDATE' and v_report.report_date <> NEW.work_date) then
      raise exception 'attendance report date or destination is inconsistent';
    end if;
    -- Existing management RPC associates a next-morning end with the report day.
    if NEW.source_clock_in_id is null then v_date := v_report.report_date; end if;
  end if;
  if TG_OP='UPDATE' and NEW.event_type='clock_in' and exists (
    select 1 from public.attendance_verifications child
    where child.source_clock_in_id=NEW.id and child.work_date is distinct from v_date
  ) then
    raise exception 'clock in report cannot change its closed shift date';
  end if;
  -- The existing management writer recreates an explicit report pair without
  -- source_clock_in_id. Never infer a start by name, nearest time or LIMIT 1.
  if TG_OP='INSERT' and NEW.event_type='clock_out'
     and NEW.source_clock_in_id is null and NEW.daily_report_id is not null then
    select count(*), min(a.confirmed_at) into v_legacy_count,v_legacy_start
    from public.attendance_verifications a
    where a.daily_report_id=NEW.daily_report_id
      and a.company_id=NEW.company_id and a.worker_id=NEW.worker_id
      and a.site_id is not distinct from NEW.site_id
      and a.route_assignment_id is not distinct from NEW.route_assignment_id
      and a.vehicle_id is not distinct from NEW.vehicle_id
      and a.event_type='clock_in';
    if v_legacy_count=1 and
       date_trunc('minute',NEW.confirmed_at at time zone 'Asia/Tokyo')
       = date_trunc('minute',v_legacy_start at time zone 'Asia/Tokyo') then
      raise exception using errcode='22023',
        message='出勤と同じ時刻のため退勤できません。時刻が進んでから再度お試しください';
    end if;
  end if;
  if TG_OP='INSERT' then NEW.work_date := v_date; end if;
  return NEW;
end $function$

CREATE OR REPLACE FUNCTION private.route_journey_visit_before_clock_out()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare source public.attendance_verifications%rowtype;
 active private.route_journey_visit_events%rowtype; origin text; payload jsonb;
 ended timestamptz; started timestamptz;
begin
 if new.event_type='clock_out' and new.source_clock_in_id is not null then
  select * into source from public.attendance_verifications where id=new.source_clock_in_id;
  if source.route_assignment_id is null then return new; end if;
  if source.company_id is distinct from new.company_id or source.worker_id is distinct from new.worker_id or
     auth.uid() is null or not private.account_access_allowed() or
     not exists(select 1 from public.company_members where company_id=source.company_id and user_id=auth.uid()) or
     not (exists(select 1 from public.workers where id=source.worker_id and company_id=source.company_id and user_id=auth.uid()) or private.has_company_feature(source.company_id,'can_manage_attendance')) then
   raise exception 'route clock-out source not permitted' using errcode='42501';
  end if;
  perform 1 from public.companies where id=source.company_id for key share;
  select * into source from public.attendance_verifications where id=new.source_clock_in_id for update;
  if current_setting('transaction_isolation') <> 'read committed' then
   raise exception 'visit clock-out guard requires read committed';
  end if;
  select s.* into active from private.route_journey_visit_events s
   where s.source_clock_in_id=source.id and s.kind='start'
   and not exists(select 1 from private.route_journey_visit_events e where e.start_capture_id=s.capture_id and e.kind='end');
  if found then
   -- Intermediate visits still require explicit movement. The last visit ends
   -- atomically with clock-out; an insert failure rolls both records back.
   if exists(select 1 from public.route_stops rs where rs.route_assignment_id=source.route_assignment_id
    and not exists(select 1 from private.route_journey_visit_events v
     where v.source_clock_in_id=source.id and v.route_stop_id=rs.id and v.kind='start')) then
    raise exception 'finish current visit before clock-out';
   end if;
   select c.origin_kind, (c.payload->>'attempted_at')::timestamptz into origin,started
    from private.route_journey_captures c where c.id=active.capture_id;
   ended:=coalesce((to_jsonb(new)->>'attempted_at')::timestamptz,
                  (to_jsonb(new)->>'confirmed_at')::timestamptz,clock_timestamp());
   if not isfinite(ended) or ended<started then raise exception 'clock-out precedes final arrival'; end if;
   payload:=jsonb_build_object('capture_contract_version',1,'gps_capture_status','missing',
    'photo_capture_status','missing','gps_captured_at',null,'photo_captured_at',null,
    'photo_observed_at',null,'captured_address',null,'latitude',null,'longitude',null,
    'accuracy_m',null,'photo_storage_path',null,'attempted_at',ended);
   perform private.save_route_journey_visit(new.id,source.id,active.route_stop_id,origin,payload,'end',active.capture_id);
  end if;
 end if;
 return new;
end $function$
